mapper.select:
SELECT pep.id, pep.prescription_name AS prescriptionName, p.name AS patientName, p.gender, TIMESTAMPDIFF(YEAR, p.birth_date, CURDATE()) AS age, p.medical_record_no AS medicalRecordNumber, p.disease_type AS diseaseType, p.enrollment_institution AS enrollmentInstitution, pep.execution_institution AS executionInstitution, pep.prescription_status AS prescriptionStatus, pep.prescribing_doctor AS prescribingDoctor, pep.created_time AS createdTime, p.birth_date AS birthDate FROM patient_exercise_prescription pep LEFT JOIN patient p ON pep.patient_id = p.id
AND pep.patient_id = #{query.patientId}
AND p.disease_type = #{query.diseaseType}
AND pep.prescription_status = #{query.prescriptionStatus}
AND p.enrollment_institution = #{query.enrollmentInstitution}
AND pep.execution_institution = #{query.executionInstitution}
AND ( p.name LIKE CONCAT('%', #{query.searchKeyword}, '%') OR p.medical_record_no LIKE CONCAT('%', #{query.searchKeyword}, '%') )
ORDER BY pep.created_time DESC
